import{_ as t,c as a,o as r,aA as n}from"./chunks/framework.BqlMnZ86.js";const p=JSON.parse('{"title":"MANTIS.jl Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function i(s,e,l,d,c,m){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="MANTIS.jl-Documentation" tabindex="-1">MANTIS.jl Documentation <a class="header-anchor" href="#MANTIS.jl-Documentation" aria-label="Permalink to &quot;MANTIS.jl Documentation {#MANTIS.jl-Documentation}&quot;">​</a></h1><h2 id="Introduction" tabindex="-1">Introduction <a class="header-anchor" href="#Introduction" aria-label="Permalink to &quot;Introduction {#Introduction}&quot;">​</a></h2><p>Welcome to the documentation for <code>MANTIS.jl</code>, a julia package for high-order structure-preserving finite element methods. This package is designed around structure-preserving/mimetic methods. It has extensive support for basis functions; &#39;standard&#39; mimetic finite elements, multi-patch splines, and hierarchical splines. It is free and open source (<a href="https://github.com/MantisFEM/Mantis.jl/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT license</a>).</p><div class="warning custom-block"><p class="custom-block-title">Under development</p><p>Mantis.jl is under active development and can still undergo large changes.</p></div><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><ol><li><p><a id="Gerritsma2011"></a> M. Gerritsma. <a href="https://doi.org/10.1007/978-3-642-15337-2_17" target="_blank" rel="noreferrer"><em>Edge Functions for Spectral Element Methods</em></a>. In: <em>Spectral and High Order Methods for Partial Differential Equations</em>, Vol. 76 of <em>Lecture Notes in Computational Science and Engineering</em>, edited by J. S. Hesthaven and E. M. Ronquist (Springer, 2011); pp. 199–207.</p></li><li><p><a id="Costa2000"></a> B. Costa and W. S. Don. <em>On the computation of high order pseudospectral derivatives</em>. <a href="https://doi.org/10.1016/S0168-9274(99)00078-1" target="_blank" rel="noreferrer">Applied Numerical Mathematics <strong>33</strong>, 151–159</a> (2000).</p></li><li><p><a id="Dangella2018"></a> D. D’Angella, S. Kollmannsberger, E. Rank and A. Reali. <em>Multi-level Bézier extraction for hierarchical local refinement of Isogeometric Analysis</em>. <a href="https://doi.org/10.1016/j.cma.2017.08.017" target="_blank" rel="noreferrer">Computer Methods in Applied Mechanics and Engineering <strong>328</strong>, 147–174</a> (2018).</p></li><li><p><a id="Trefethen2008"></a> L. N. Trefethen. <em>Is Gauss quadrature better than Clenshaw-Curtis?</em> <a href="https://doi.org/10.1137/060659831" target="_blank" rel="noreferrer">SIAM Review <strong>50</strong>, 67–87</a> (2008).</p></li><li><p><a id="Trefethen2022"></a> L. N. Trefethen. <em>Exactness of quadrature formulas</em>. <a href="https://doi.org/10.1137/20M1389522" target="_blank" rel="noreferrer">SIAM Review <strong>64</strong>, 132–150</a> (2022).</p></li><li><p><a id="Waldvogel2006"></a> J. Waldvogel. <em>Fast construction of the Fejér and Clenshaw-Curtis quadrature rules</em>. <a href="https://doi.org/10.1007/s10543-006-0045-4" target="_blank" rel="noreferrer">BIT Numerical Mathematics <strong>46</strong>, 195–202</a> (2006).</p></li></ol>',6)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
